import{_ as p,a0 as s,w as d,s as a,ao as l,I as r,x as e,a1 as u,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"如何啓動 Ubuntu 22.04 進入救援/緊急模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何啓動 Ubuntu 22.04 進入救援/緊急模式 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何啓動 Ubuntu 22.04 進入救援/緊急模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何啓動 Ubuntu 22.04 進入救援/緊急模式 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220607 How to Boot Ubuntu 22.04 into Rescue - Emergency Mode","title":"如何啓動 Ubuntu 22.04 進入救援/緊急模式","tag":"202206","desc":""},"relativePath":"202206/20220607 How to Boot Ubuntu 22.04 into Rescue - Emergency Mode.md","filePath":"[post].md"}'),i={name:"202206/20220607 How to Boot Ubuntu 22.04 into Rescue - Emergency Mode.md"};function c(m,t,b,g,w,h){const o=s("Link");return d(),a("div",null,[t[15]||(t[15]=l('<h1 id="如何啓動-ubuntu-22-04-進入救援-緊急模式" tabindex="-1">如何啓動 Ubuntu 22.04 進入救援/緊急模式 <a class="header-anchor" href="#如何啓動-ubuntu-22-04-進入救援-緊急模式" aria-label="Permalink to “如何啓動 Ubuntu 22.04 進入救援/緊急模式”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/24/101647n4nru1ayaw4nrnue.jpg" alt=""></p><p>極客們好，將 Ubuntu 22.04（Jammy Jellyfish）啓動到<ruby>救援<rt>Rescue</rt></ruby>和<ruby>緊急<rt>Emergency</rt></ruby>模式可以重置忘記的用户密碼、修復文件系統錯誤，以及在啓動過程中禁用或啓用 systemd 服務。</p><p>在這篇文章中，我們將學習如何啓動 Ubuntu 22.04 LTS 系統進入救援和應急模式。救援模式類似於單用户模式，所有的故障排除步驟都在這裏進行。救援模式加載最小的環境並掛載根文件系統。</p><p>而在緊急模式下，我們得到的是單用户 Shell，而不啓動任何系統服務。因此，當我們無法啓動系統進入救援模式時，就需要緊急模式。</p><h3 id="啓動-ubuntu-22-04-進入救援或單用户模式" tabindex="-1">啓動 Ubuntu 22.04 進入救援或單用户模式 <a class="header-anchor" href="#啓動-ubuntu-22-04-進入救援或單用户模式" aria-label="Permalink to “啓動 Ubuntu 22.04 進入救援或單用户模式”">​</a></h3><p>前往你想啓動到救援或單用户模式的目標系統。在啓動時按下 <code>SHIFT + ESC</code> 鍵，進入 GRUB 引導加載器頁面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Default-Grub-Screen-Ubuntu-22-04.png" alt="Default-Grub-Screen-Ubuntu-22-04"></p><p>選擇第一個選項 “Ubuntu”，並按 <code>e</code> 鍵進入編輯模式。</p><p>在以 <code>linux</code> 開頭的一行末尾，刪除字符串 <code>$vt_handoff</code> 並添加字符串 <code>systemd.unit=rescue.target</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/rescue-target-ubuntu-22-04.png" alt="rescue-target-ubuntu-22-04"></p><p>做完修改後，按 <code>Ctrl + X</code> 或 <code>F10</code> 在救援模式下啓動。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Troubleshooting-Commands-in-Rescue-Mode.png" alt="Troubleshooting-Commands-in-Rescue-Mode"></p><p>進入救援模式後，運行所有的故障排除命令，並運行 <code>systemctl reboot</code> 命令來重啓系統。</p><h3 id="另一種啓動系統進入救援模式的方法" tabindex="-1">另一種啓動系統進入救援模式的方法 <a class="header-anchor" href="#另一種啓動系統進入救援模式的方法" aria-label="Permalink to “另一種啓動系統進入救援模式的方法”">​</a></h3><p>重新啓動系統並按下 <code>ESC + Shift</code> 鍵，進入 GRUB 啓動界面。</p><p>選擇第二個選項 “<ruby>Ubuntu 高級選項<rt>Advanced Options for Ubuntu</rt></ruby>”-&gt;選擇“<ruby>恢復模式<rt>recovery mode</rt></ruby>”選項並點擊回車-&gt;選擇 <ruby>root（進入 root shell 提示符）<rt>root (Drop to root shell prompt)</rt></ruby>。</p><p>下面是一個例子：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Boot-Ubuntu-22-04-Rescue-Mode.gif" alt="Boot-Ubuntu-22-04-Rescue-Mode"></p><p>當你有了 root Shell，運行命令來恢復和修復系統問題，最後使用 <code>systemctl reboot</code> 來重啓系統。</p><h3 id="引導-ubuntu-22-04-進入緊急模式" tabindex="-1">引導 Ubuntu 22.04 進入緊急模式 <a class="header-anchor" href="#引導-ubuntu-22-04-進入緊急模式" aria-label="Permalink to “引導 Ubuntu 22.04 進入緊急模式”">​</a></h3><p>要啓動系統進入緊急模式，首先進入 GRUB 頁面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Default-Grub-Screen-Ubuntu-22-04.png" alt="Default-Grub-Screen-Ubuntu-22-04"></p><p>選擇第一個選項 “Ubuntu” 並按 <code>e</code> 鍵進行編輯。尋找以 <code>linux</code> 開頭的一行，移到該行的末尾，刪除字符串 <code>$vt_handoff</code> 並添加字符串 <code>systemd.unit=emergency.target</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Emergency-Mode-Ubuntu-22-04.png" alt="Emergency-Mode-Ubuntu-22-04"></p><p>按 <code>Ctrl + X</code> 或 <code>F10</code> 將系統啓動到緊急模式。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/06/Command-in-Emergency-Mode-Ubuntu-22-04.png" alt="Command-in-Emergency-Mode-Ubuntu-22-04"></p><p>同樣，在緊急模式下，你可以在這個模式下執行所有的故障排除，完成後，就用 <code>systemctl reboot</code> 命令重啓系統。</p><p>這篇文章的內容就這些。文章內容豐富，不要猶豫，請在你的技術朋友中分享它。請在下面的評論區發表你的疑問和反饋。</p><hr>',30)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),u(o,{href:"https://www.linuxtechi.com/boot-ubuntu-22-04-rescue-emergency-mode/"},{default:n(()=>[...t[0]||(t[0]=[e("https://www.linuxtechi.com/boot-ubuntu-22-04-rescue-emergency-mode/",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=e("作者：",-1)),u(o,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...t[2]||(t[2]=[e("Pradeep Kumar",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),u(o,{href:"https://github.com/lkxed"},{default:n(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),u(o,{href:"https://github.com/geekpi"},{default:n(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),u(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=e("本文由 ",-1)),u(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),u(o,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const x=p(i,[["render",c]]);export{U as __pageData,x as default};
